#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[1111111];
int f[1111111],d[1111111];
int dp[1111111][22],vis[1111111];
int fff[1111111],ffff[1111111];
int aa[1111111],bb[1111111];
void dfs(int p,int g,int fa){
	dp[p][0]=fa;
	d[p]=g;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int ff(int p){
	int x=aa[p];
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			x+=ff(v[p][i]);
		}
	}
	return fff[p]=x;
}
int fffff(int p){
	int x=bb[p];
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			x+=fffff(v[p][i]);
		}
	}
	return ffff[p]=x;
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return x;
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i];
			y=dp[y][i];
		}
	}    
	return dp[x][0];
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,m;
	cin>>n>>m;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1,0,0);
	for(int i=1;i<=m;i++){
		int x,y;
		cin>>x>>y;
		aa[x]+=1;
		aa[y]+=1;
		aa[f[lca(x,y)]]-=1;
		aa[lca(x,y)]-=1;
	}
	int x,y;
	cin>>x>>y;
	bb[x]++;
	bb[y]++;
	bb[f[lca(x,y)]]--;
	bb[lca(x,y)]--;
	vis[1]=1;
	ff(1);
	memset(vis,0,sizeof(vis));
	vis[1]=1;
	fffff(1);
	int ans=0;
	for(int i=1;i<=n;i++){
//		cout<<fff[i]<<" "<<ffff[i]<<endl;
		if(fff[i]==0&&ffff[i]>0){
			ans++;
		}
	}
	cout<<ans;
    return 0;
}
